# Thermal Threshold Analysis# Author: J. Judson Wynne# Date: 24 October 2026# Purpose: Derive thermal reference values from Lang (1979) body-temperature data using linear mixed-effects models (LMMs).# Description# This script reproduces the analyses used to estimate thermal reference values from the body temperature (Tb) data reported by Lang (1979). Linear mixed-effects models (LMMs) were fitted using crocodile identity as a random intercept. Two analyses were conducted:# 1. All observations pooled across experimental conditions.# 2. A fitted model using the Fasted Nighttime condition as the reference level.# The upper Wald 95% confidence interval bound from the all-observations model was adopted as the modeled thermal reference value used in the manuscript.library(lme4)library(lmerTest)library(performance)library(DHARMa)# Load Datadat <- read.csv("Croc_Lang.csv")dat$Crocodile_ID <- factor(dat$Crocodile_ID)dat$Condition <- factor(dat$Condition)levels(dat$Condition)# MODEL 1# All observations pooled across experimental conditionsmod_all <- lmer(Temperature ~ 1 + (1 | Crocodile_ID), data = dat, REML = TRUE)confint_all <- confint(mod_all, method = "profile")r2_all <- performance::r2(mod_all)varcomp_all <- as.data.frame(VarCorr(mod_all))# Diagnostics: Model 1sim_all <- simulateResiduals(mod_all)diag_all <- data.frame(Model = "All observations", Uniformity_p = testUniformity(sim_all)$p.value, Dispersion_p = testDispersion(sim_all)$p.value, Outliers_p = testOutliers(sim_all)$p.value)# MODEL 2# Fasted nighttime as reference leveldat_fn <- datdat_fn$Condition <- relevel(dat_fn$Condition, ref = "Fasted nighttime")mod_fn <- lmer(Temperature ~ Condition + (1 | Crocodile_ID), data = dat_fn, REML = TRUE)confint_fn <- confint(mod_fn, method = "profile")r2_fn <- performance::r2(mod_fn)varcomp_fn <- as.data.frame(VarCorr(mod_fn))# Diagnostics: Model 2sim_fn <- simulateResiduals(mod_fn)diag_fn <- data.frame(Model = "Fasted nighttime reference", Uniformity_p = testUniformity(sim_fn)$p.value, Dispersion_p = testDispersion(sim_fn)$p.value, Outliers_p = testOutliers(sim_fn)$p.value)# Extract Results: Model 1results_all <- data.frame(Model = "All observations", Estimate = fixef(mod_all)[1], SE = summary(mod_all)$coefficients[1, "Std. Error"], df = summary(mod_all)$coefficients[1, "df"], t = summary(mod_all)$coefficients[1, "t value"], p = summary(mod_all)$coefficients[1, "Pr(>|t|)"], CI_Lower = confint_all["(Intercept)", 1], CI_Upper = confint_all["(Intercept)", 2], Conditional_R2 = r2_all$R2_conditional)# Extract Results: Model 2# Intercept represents Fasted Nighttimecoef_fn <- summary(mod_fn)$coefficientsresults_fn <- data.frame(Model = "Fasted nighttime reference", Estimate = coef_fn[1, "Estimate"], SE = coef_fn[1, "Std. Error"], df = coef_fn[1, "df"], t = coef_fn[1, "t value"], p = coef_fn[1, "Pr(>|t|)"], CI_Lower = confint_fn["(Intercept)", 1], CI_Upper = confint_fn["(Intercept)", 2], Conditional_R2 = r2_fn$R2_conditional)# Export Tableswrite.csv(rbind(results_all, results_fn), "Model_Results.csv", row.names = FALSE)write.csv(rbind(diag_all, diag_fn), "Model_Diagnostics.csv", row.names = FALSE)write.csv(rbind(transform(varcomp_all, Model = "All observations"), transform(varcomp_fn, Model = "Fasted nighttime reference")), "Variance_Components.csv", row.names = FALSE)